DO $migration$
DECLARE col record;
BEGIN
  FOR col IN
    SELECT table_name, column_name, data_type FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name IN ('articles','pages','pillar_pages','products','applications','page_blocks','settings','authors')
      AND data_type IN ('text','character varying','jsonb')
  LOOP
    EXECUTE format(
      'UPDATE %I SET %I = pg_temp.cms_scene_image(%I::text)%s WHERE %I::text LIKE ''%%/assets/img/%%'' AND pg_temp.cms_scene_image(%I::text) IS DISTINCT FROM %I::text',
      col.table_name, col.column_name, col.column_name,
      CASE WHEN col.data_type = 'jsonb' THEN '::jsonb' ELSE '' END,
      col.column_name, col.column_name, col.column_name
    );
  END LOOP;
END $migration$;

