UPDATE pages SET hero_image = '/assets/img/generated/data-privacy.webp'
WHERE slug IN ('privacy','terms','legal','gdpr')
  AND hero_image IN ('/assets/img/generated/article-bms-pcm-smart.webp', '/assets/img/generated/data-privacy.webp');

UPDATE pages SET hero_image = '/assets/img/generated/home-battery-range.webp'
WHERE slug = 'applications/index' AND hero_image IN ('/assets/img/generated/article-bms-pcm-smart.webp', '/assets/img/generated/data-privacy.webp', '/assets/img/generated/home-battery-range.webp');

DROP FUNCTION pg_temp.cms_scene_image(text);

-- Fill missing bundled product covers without touching operator-supplied media.
WITH product_images(slug, image) AS (VALUES
  ('lp-503562-1200', '/assets/img/generated/polymer-cells.webp'),
  ('lp-round-1240-200', '/assets/img/generated/round-polymer-cells.webp'),
  ('lir2032-40', '/assets/img/generated/coin-cells.webp'),
  ('ml2032-65-reflow', '/assets/img/generated/article-reflow-profile-ml-coin-cell.webp'),
  ('lir2450-120', '/assets/img/generated/coin-cells.webp')
)
UPDATE products p SET cover_url = i.image FROM product_images i
WHERE p.slug = i.slug AND COALESCE(p.cover_url, '') = '';
